{
}

Method.Source:
/// <summary>
/// initialize of entity dataSource
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
public void initializeEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    next initializeEntityDataSource(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(EcoResProductBarcodeAssociationEntity, InventItemBarcode) 
        && _entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert)
    {
        InventItemBarcode   itemBarcode = _dataSourceCtx.getBuffer();
        itemBarcode.METDefault = NoYes::Yes;
        _dataSourceCtx.setBuffer(itemBarcode);
    }
}
